injectJs:
function $(a){
	return document.querySelector(a)
	}
function $$(a){
	return document.querySelectorAll(a)
	}

href = window.location.href

if(href.search(/#/)==-1){

author = $$(".authorname");
html = "";
node = $$(".read");

for(i=0;i<author.length;i++){
		a = author[i].innerText.replace(/加书签 举报/g,'').replace(/☆☆☆/g,'');
	html+='<div class="author">'+a+"</div>"+node[i].innerHTML+"<hr><br>";
	}

	try{
	zhu = $("#msgsubject").outerHTML+"<br><br>";
	page = $$("#pager_top")[0]?$$("#pager_top")[0].innerHTML:"";
	$("body").innerHTML = page+"<br>" + zhu + html +page
  $("#msgsubject").style.cssText = 'background:#fff;border-radius:15px;box-shadow:1px 1px 3px #555;	text-indent:2em;	padding:2px 5px'
 $("body").style.cssText = "background:#fff"
for(i=0;i<author.length;i++){
		$$(".author")[i].style.cssText="font-size:12px;color:green"
	}
}catch(err){
	}
}

